import React, { useState } from 'react';
import { NavLink, Outlet } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTachometerAlt, faUserGraduate, faChalkboardTeacher, faMoneyBillWave, faCog, faQuestionCircle, faChevronLeft, faChevronRight } from '@fortawesome/free-solid-svg-icons';
import './../assets/css/dashboard-content.css';

const AdminDashboard = () => {
  const [isCollapsed, setIsCollapsed] = useState(false);

  const toggleSidebar = () => {
    setIsCollapsed(!isCollapsed);
  };

  return (
    <div className="dashboard-container">
      {/* Sidebar */}
      <aside className={`sidebar ${isCollapsed ? 'collapsed' : ''}`}>
        <div className="sidebar-header">
          <h1 className="app-logo">ECA</h1>
          <button className="collapse-btn" onClick={toggleSidebar}>
            <FontAwesomeIcon icon={isCollapsed ? faChevronRight : faChevronLeft} />
          </button>
        </div>
        <nav className="sidebar-menu">
          <NavLink to="/admin-dashboard" end className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faTachometerAlt} />
            {!isCollapsed && <span>Dashboard</span>}
          </NavLink>
          <NavLink to="/admin-dashboard/students" className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faUserGraduate} />
            {!isCollapsed && <span>Student Management</span>}
          </NavLink>
          <NavLink to="/admin-dashboard/teachers" className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faChalkboardTeacher} />
            {!isCollapsed && <span>Teacher Management</span>}
          </NavLink>
          <NavLink to="/admin-dashboard/fees" className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faMoneyBillWave} />
            {!isCollapsed && <span>Fee Management</span>}
          </NavLink>
          <NavLink to="/admin-dashboard/courses" className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faCog} />
            {!isCollapsed && <span>Courses</span>}
          </NavLink>
        </nav>
        <div className="sidebar-footer">
          <div className="sidebar-footer-item">
            <FontAwesomeIcon icon={faQuestionCircle} />
            {!isCollapsed && <span>Help & Support</span>}
          </div>
          <div className="sidebar-profile">
            <img src="/path/to/profile-pic.png" alt="Admin" className="profile-pic" />
            <div className="profile-info">
              {!isCollapsed && <p className="profile-name">Admin User</p>}
              {!isCollapsed && <p className="profile-email">admin@eca.com</p>}
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className={`main-content ${isCollapsed ? 'full-width' : ''}`}>
        <Outlet />
      </main>
    </div>
  );
};

export default AdminDashboard;
